/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const RDBBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *RDBBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// The RigidDiskBlock and partitions of a unit of a block device, read
    /// into a handle; null, and why in `err`, when the device cannot be used.
    pub fn OpenRDB(self: *RDBBase, device: [*:0]const u8, unit: u32, err: ?*i32) ?*rdb.RDBHandle {
        return libraries.call(self, LVO.OpenRDB, Fn.OpenRDB, .{ device, unit, err });
    }

    /// The handle, its partitions and the device let go of.
    pub fn CloseRDB(self: *RDBBase, handle: ?*rdb.RDBHandle) void {
        return libraries.call(self, LVO.CloseRDB, Fn.CloseRDB, .{handle});
    }

    /// A fresh RigidDiskBlock for the whole medium in the handle, with no
    /// partitions: written by WriteRDB.
    pub fn InitRDB(self: *RDBBase, handle: *rdb.RDBHandle) i32 {
        return libraries.call(self, LVO.InitRDB, Fn.InitRDB, .{handle});
    }

    /// The partition after `previous` on the handle's list, or the first.
    pub fn NextPartition(self: *RDBBase, handle: *rdb.RDBHandle, previous: ?*rdb.RDBPartition) ?*rdb.RDBPartition {
        return libraries.call(self, LVO.NextPartition, Fn.NextPartition, .{ handle, previous });
    }

    /// The partition called `name`, in any case.
    pub fn FindPartition(self: *RDBBase, handle: *rdb.RDBHandle, name: [*:0]const u8) ?*rdb.RDBPartition {
        return libraries.call(self, LVO.FindPartition, Fn.FindPartition, .{ handle, name });
    }

    /// A new partition called `name` over cylinders `low_cyl` to `high_cyl`
    /// (0 and 0: the largest free run) for the file system `dos_type`.
    pub fn AddPartition(self: *RDBBase, handle: *rdb.RDBHandle, name: [*:0]const u8, low_cyl: u32, high_cyl: u32, dos_type: u32) i32 {
        return libraries.call(self, LVO.AddPartition, Fn.AddPartition, .{ handle, name, low_cyl, high_cyl, dos_type });
    }

    /// A partition taken off the handle's list and freed.
    pub fn RemPartition(self: *RDBBase, handle: *rdb.RDBHandle, partition: *rdb.RDBPartition) void {
        return libraries.call(self, LVO.RemPartition, Fn.RemPartition, .{ handle, partition });
    }

    /// The handle's table checked and written to the disk.
    pub fn WriteRDB(self: *RDBBase, handle: *rdb.RDBHandle) i32 {
        return libraries.call(self, LVO.WriteRDB, Fn.WriteRDB, .{handle});
    }

    /// A device node for a partition on dos's list, named as the partition
    /// (with dots added while the name is taken), its handler started with
    /// RDBMF_START; the name used goes where `name` points.
    pub fn MountPartition(self: *RDBBase, handle: *rdb.RDBHandle, partition: *rdb.RDBPartition, name: ?*rdb.MountName, flags: u32) i32 {
        return libraries.call(self, LVO.MountPartition, Fn.MountPartition, .{ handle, partition, name, flags });
    }

    /// The file system after `previous` on the handle's list of the file
    /// systems kept in the table, or the first.
    pub fn NextFileSystem(self: *RDBBase, handle: *rdb.RDBHandle, previous: ?*rdb.RDBFileSystem) ?*rdb.RDBFileSystem {
        return libraries.call(self, LVO.NextFileSystem, Fn.NextFileSystem, .{ handle, previous });
    }

    /// A handler's load file, `size` bytes at `code`, kept in the table for
    /// the partitions of `dos_type` - in place of one kept for it already -
    /// once WriteRDB writes it.
    pub fn AddFileSystem(self: *RDBBase, handle: *rdb.RDBHandle, dos_type: u32, code: [*]const u8, size: u32) i32 {
        return libraries.call(self, LVO.AddFileSystem, Fn.AddFileSystem, .{ handle, dos_type, code, size });
    }

    /// A file system taken out of the handle's table and freed.
    pub fn RemFileSystem(self: *RDBBase, handle: *rdb.RDBHandle, file_system: *rdb.RDBFileSystem) void {
        return libraries.call(self, LVO.RemFileSystem, Fn.RemFileSystem, .{ handle, file_system });
    }

    /// The GPT partition after `previous` on the handle's list, or the first.
    pub fn NextGPTPartition(self: *RDBBase, handle: *rdb.RDBHandle, previous: ?*rdb.GPTPartition) ?*rdb.GPTPartition {
        return libraries.call(self, LVO.NextGPTPartition, Fn.NextGPTPartition, .{ handle, previous });
    }

    /// A device node for a GPT partition on dos's list, named `name` (with
    /// dots added while the name is taken), for the file system its first
    /// block holds; the name used goes where `mounted` points.
    pub fn MountGPTPartition(self: *RDBBase, handle: *rdb.RDBHandle, partition: *rdb.GPTPartition, name: [*:0]const u8, mounted: ?*rdb.MountName, flags: u32) i32 {
        return libraries.call(self, LVO.MountGPTPartition, Fn.MountGPTPartition, .{ handle, partition, name, mounted, flags });
    }

    /// A fresh GPT for the whole medium in the handle, with no partitions:
    /// written by WriteGPT.
    pub fn InitGPT(self: *RDBBase, handle: *rdb.RDBHandle) i32 {
        return libraries.call(self, LVO.InitGPT, Fn.InitGPT, .{handle});
    }

    /// A new GPT partition, as `entry` gives its type, blocks (0 and 0: the
    /// largest free run), attributes and name; null, and why in `err`, when
    /// it cannot be one.
    pub fn AddGPTPartition(self: *RDBBase, handle: *rdb.RDBHandle, entry: *const gpt.Entry, err: ?*i32) ?*rdb.GPTPartition {
        return libraries.call(self, LVO.AddGPTPartition, Fn.AddGPTPartition, .{ handle, entry, err });
    }

    /// A GPT partition taken off the handle's list and freed.
    pub fn RemGPTPartition(self: *RDBBase, handle: *rdb.RDBHandle, partition: *rdb.GPTPartition) void {
        return libraries.call(self, LVO.RemGPTPartition, Fn.RemGPTPartition, .{ handle, partition });
    }

    /// The handle's GPT checked and written to the disk, both copies.
    pub fn WriteGPT(self: *RDBBase, handle: *rdb.RDBHandle) i32 {
        return libraries.call(self, LVO.WriteGPT, Fn.WriteGPT, .{handle});
    }

    /// The handle's GPT taken out of it, for a table over the whole disk,
